compile.workshop:
variables {
    global:
        0: a
        1: i
}

rule ("continue for") {
    event {
        Ongoing - Global;
    }
    actions {
        For Global Variable(i, 0, 3, 1);
            Skip If(Compare(Global.i, ==, 1), 1);
            Modify Global Variable(i, Add, 1);
            //__label_continue_2__:
        End;
    }
}

rule ("continue while") {
    event {
        Ongoing - Global;
    }
    actions {
        While(Compare(Global.i, <, 3));
            Skip If(Compare(Global.i, ==, 1), 1);
            Modify Global Variable(i, Add, 1);
            //__label_continue_3__:
        End;
    }
}

rule ("continue do") {
    event {
        Ongoing - Global;
    }
    actions {
        Loop If(Compare(Global.i, ==, 1));
        Modify Global Variable(i, Add, 1);
        Loop If(Compare(Global.i, <, 3));
    }
}

rule ("dynamic goto") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Skip(Global.a);
        Set Global Variable(a, 2);
    }
}

rule ("conditional dynamic goto") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Skip If(Compare(Global.a, ==, 1), Global.a);
        Skip(Global.a);
        "pass"
        disabled Abort;
        Set Global Variable(a, 3);
    }
}

rule ("continue switch in for") {
    event {
        Ongoing - Global;
    }
    actions {
        For Global Variable(i, 0, 3, 1);
            If(True);
                Skip(Value In Array(Array(1, 0), Add(1, Index Of Array Value(Array(1), Global.i))));
            //__label_switch_5_0__:
            Skip(3);
            //__label_switch_5_default__:
            Modify Global Variable(i, Add, 1);
            End;
            Modify Global Variable(a, Add, 1);
            //__label_continue_4__:
        End;
    }
}

rule ("continue switch in while") {
    event {
        Ongoing - Global;
    }
    actions {
        While(Compare(Global.i, <, 3));
            If(True);
                Skip(Value In Array(Array(1, 0), Add(1, Index Of Array Value(Array(1), Global.i))));
            //__label_switch_7_0__:
            Skip(3);
            //__label_switch_7_default__:
            Modify Global Variable(i, Add, 1);
            End;
            Modify Global Variable(a, Add, 1);
            //__label_continue_6__:
        End;
    }
}

rule ("continue switch in do") {
    event {
        Ongoing - Global;
    }
    actions {
        If(True);
            Skip(Value In Array(Array(1, 0), Add(1, Index Of Array Value(Array(1), Global.i))));
        //__label_switch_8_0__:
        Loop;
        //__label_switch_8_default__:
        Modify Global Variable(i, Add, 1);
        End;
        Modify Global Variable(a, Add, 1);
        Loop If(Compare(Global.i, <, 3));
    }
}

rule ("rule start") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Loop;
    }
}

